<?php
 namespace Pterodactyl\Http\Requests\Api\Client\Servers\Rust; use Pterodactyl\Models\Server; use Pterodactyl\Models\Permission; class RustWipesManageRequest extends RustWipesRequest { public const REQUIRED = [ Permission::ACTION_SCHEDULE_UPDATE, Permission::ACTION_FILE_DELETE, Permission::ACTION_CONTROL_STOP, Permission::ACTION_CONTROL_START, ]; public function permission(): string { return Permission::ACTION_SCHEDULE_UPDATE; } public function authorize(): bool { if (!parent::authorize()) { return false; } $server = $this->route()->parameter('server'); foreach (self::REQUIRED as $permission) { if (!$this->user()->can($permission, $server)) { return false; } } return true; } public function canChangeStartup(Server $server): bool { return $this->user()->can(Permission::ACTION_STARTUP_UPDATE, $server); } } 